class Base {
public:
    virtual void foo();  // Declares a virtual function, triggering vtable creation
    // Implementation note: The compiler adds a vptr to the class layout.
};

class Derived : public Base {
public:
    void foo() override;  // Overrides the virtual function; the compiler updates the vtable entry
    // Note: Derived's vtable will point to its own foo() implementation.
};
